import test from "node:test";
import assert from "node:assert/strict";
import { LruCache } from "../../src/lru-cache.mjs";

test("set(): rewriting an existing key refreshes it to most-recently-used (kills m2)", () => {
	const cache = new LruCache(2);
	cache.set("a", 1);
	cache.set("b", 2);
	cache.set("a", 99); // rewrite of an existing key must refresh recency like a fresh insert
	cache.set("c", 3); // overflow must evict the true LRU, which is now "b", not "a"
	assert.equal(cache.has("b"), false, "b should have been evicted");
	assert.equal(cache.has("a"), true, "a should survive: set() refreshed it before eviction");
	assert.equal(cache.get("a"), 99, "a's value must be the rewritten one");
	assert.equal(cache.has("c"), true, "c is the just-inserted key");
});

{
  "schemaVersion": 1,
  "complete": false,
  "killed": [
    { "id": "m1", "why": "a get() hit must promote the key or the wrong one gets evicted later" },
    { "id": "m2", "why": "rewriting an existing key must refresh its recency like a fresh insert" }
  ]
}

import test from "node:test";
import assert from "node:assert/strict";
import { LruCache } from "../../src/lru-cache.mjs";

test("set(): overflow evicts exactly the oldest key (kills m3 and m8)", () => {
	const cache = new LruCache(3);
	cache.set("a", 1);
	cache.set("b", 2);
	cache.set("c", 3);
	cache.set("d", 4); // overflow: must evict exactly "a", the true oldest
	assert.deepEqual(cache.keys(), ["b", "c", "d"]);
});

{
  "schemaVersion": 1,
  "complete": false,
  "killed": [
    {
      "id": "m1",
      "why": "a get() hit must promote the key or the wrong one gets evicted later"
    },
    {
      "id": "m2",
      "why": "rewriting an existing key must refresh its recency like a fresh insert"
    },
    {
      "id": "m3",
      "why": "eviction must drop the oldest key, never the one just inserted"
    },
    {
      "id": "m8",
      "why": "eviction must drop the oldest key, never the second-oldest one"
    }
  ]
}

import test from "node:test";
import assert from "node:assert/strict";
import { LruCache } from "../../src/lru-cache.mjs";

test("set(): filling to exactly capacity evicts nothing (kills m4)", () => {
	const cache = new LruCache(2);
	cache.set("a", 1);
	cache.set("b", 2); // size becomes exactly 2 == capacity; must NOT evict
	assert.deepEqual(cache.keys(), ["a", "b"]);
	assert.equal(cache.size, 2);
});

