import test from "node:test";
import assert from "node:assert/strict";
import { LruCache } from "../../src/lru-cache.mjs";

test("delete(): actually removes the entry, not just reports presence (kills m5)", () => {
	const cache = new LruCache(2);
	cache.set("a", 1);
	const returned = cache.delete("a");
	assert.equal(returned, true, "delete's own return value cannot distinguish this mutant");
	assert.equal(cache.has("a"), false);
	assert.equal(cache.get("a"), undefined);
	assert.deepEqual(cache.keys(), []);
});

