import assert from "node:assert/strict";
import { LruCache } from "../../src/lru-cache.mjs";

test("has(): asking never promotes the key (kills m6)", () => {
	const cache = new LruCache(2);
	cache.set("a", 1);
	cache.set("b", 2);
	cache.has("a"); // a query must not count as a use
	cache.set("c", 3); // overflow: the true oldest, "a", must be evicted
	assert.deepEqual(cache.keys(), ["b", "c"]);
});

